-- Table structure for `pesertas`
-- -----------------------------
DROP TABLE IF EXISTS `pesertas`;
CREATE TABLE `pesertas` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `angkatan_id` bigint unsigned DEFAULT NULL,
  `kelas_mapel_id` bigint unsigned DEFAULT NULL,
  `nip` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jenis_kelamin` enum('Laki-laki','Perempuan') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Laki-laki',
  `instansi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jabatan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `golongan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `pesertas_nip_unique` (`nip`),
  KEY `pesertas_angkatan_id_foreign` (`angkatan_id`),
  KEY `pesertas_kelas_mapel_id_foreign` (`kelas_mapel_id`),
  CONSTRAINT `pesertas_angkatan_id_foreign` FOREIGN KEY (`angkatan_id`) REFERENCES `angkatans` (`id`) ON DELETE SET NULL,
  CONSTRAINT `pesertas_kelas_mapel_id_foreign` FOREIGN KEY (`kelas_mapel_id`) REFERENCES `kelas_mapels` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------
-- Records for `pesertas`
-- -----------------------------

-- -----------------------------
-- Table structure for `presensis`
-- -----------------------------
DROP TABLE IF EXISTS `presensis`;
CREATE TABLE `presensis` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `peserta_id` bigint unsigned NOT NULL,
  `jadwal_id` bigint unsigned DEFAULT NULL,
  `kelas_mapel_id` bigint unsigned DEFAULT NULL,
  `tanggal` date NOT NULL,
  `status_kehadiran` enum('Hadir','Izin','Sakit','Alpa') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Hadir',
  `waktu_presensi` time DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `presensis_peserta_id_foreign` (`peserta_id`),
  KEY `presensis_jadwal_id_foreign` (`jadwal_id`),
  KEY `presensis_kelas_mapel_id_foreign` (`kelas_mapel_id`),
  CONSTRAINT `presensis_jadwal_id_foreign` FOREIGN KEY (`jadwal_id`) REFERENCES `jadwals` (`id`) ON DELETE SET NULL,
  CONSTRAINT `presensis_kelas_mapel_id_foreign` FOREIGN KEY (`kelas_mapel_id`) REFERENCES `kelas_mapels` (`id`) ON DELETE SET NULL,
  CONSTRAINT `presensis_peserta_id_foreign` FOREIGN KEY (`peserta_id`) REFERENCES `pesertas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------
-- Records for `presensis`
-- -----------------------------

-- -----------------------------
-- Table structure for `realisasi_jadwals`
-- -----------------------------
DROP TABLE IF EXISTS `realisasi_jadwals`;
CREATE TABLE `realisasi_jadwals` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `jadwal_id` bigint unsigned NOT NULL,
  `tanggal_realisasi` date NOT NULL,
  `jam_mulai_aktual` time NOT NULL,
  `jam_selesai_aktual` time NOT NULL,
  `jp_aktual` decimal(5,2) NOT NULL DEFAULT '0.00',
  `jp_dibayarkan` decimal(5,2) NOT NULL DEFAULT '0.00',
  `status` enum('Terlaksana','Dibatalkan') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Terlaksana',
  `alasan_batal` text COLLATE utf8mb4_unicode_ci,
  `catatan` text COLLATE utf8mb4_unicode_ci,
  `diverifikasi_oleh` bigint unsigned DEFAULT NULL,
  `diverifikasi_pada` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `realisasi_jadwals_jadwal_id_unique` (`jadwal_id`),
  KEY `realisasi_jadwals_diverifikasi_oleh_foreign` (`diverifikasi_oleh`),
  KEY `realisasi_jadwals_tanggal_realisasi_status_index` (`tanggal_realisasi`,`status`),
  CONSTRAINT `realisasi_jadwals_diverifikasi_oleh_foreign` FOREIGN KEY (`diverifikasi_oleh`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `realisasi_jadwals_jadwal_id_foreign` FOREIGN KEY (`jadwal_id`) REFERENCES `jadwals` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=345 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------
-- Records for `realisasi_jadwals`
-- -----------------------------

-- -----------------------------
-- Table structure for `realisasi_pengajars`
-- -----------------------------
DROP TABLE IF EXISTS `realisasi_pengajars`;
CREATE TABLE `realisasi_pengajars` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `realisasi_jadwal_id` bigint unsigned NOT NULL,
  `penugasan_pengajar_id` bigint unsigned DEFAULT NULL,
  `jenis_pengajar` enum('Widyaiswara','Narasumber') COLLATE utf8mb4_unicode_ci NOT NULL,
  `widyaiswara_id` bigint unsigned DEFAULT NULL,
  `narasumber_id` bigint unsigned DEFAULT NULL,
  `jp_aktual` decimal(5,2) NOT NULL DEFAULT '0.00',
  `jp_dibayarkan` decimal(5,2) NOT NULL DEFAULT '0.00',
  `status_kehadiran` enum('Hadir','Izin','Sakit','Digantikan') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Hadir',
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `realisasi_pengajars_penugasan_pengajar_id_foreign` (`penugasan_pengajar_id`),
  KEY `realisasi_pengajars_widyaiswara_id_foreign` (`widyaiswara_id`),
  KEY `realisasi_pengajars_narasumber_id_foreign` (`narasumber_id`),
  KEY `realisasi_pengajars_realisasi_jadwal_id_widyaiswara_id_index` (`realisasi_jadwal_id`,`widyaiswara_id`),
  KEY `realisasi_pengajars_realisasi_jadwal_id_narasumber_id_index` (`realisasi_jadwal_id`,`narasumber_id`),
  CONSTRAINT `realisasi_pengajars_narasumber_id_foreign` FOREIGN KEY (`narasumber_id`) REFERENCES `narasumbers` (`id`) ON DELETE SET NULL,
  CONSTRAINT `realisasi_pengajars_penugasan_pengajar_id_foreign` FOREIGN KEY (`penugasan_pengajar_id`) REFERENCES `penugasan_pengajars` (`id`) ON DELETE SET NULL,
  CONSTRAINT `realisasi_pengajars_realisasi_jadwal_id_foreign` FOREIGN KEY (`realisasi_jadwal_id`) REFERENCES `realisasi_jadwals` (`id`) ON DELETE CASCADE,
  CONSTRAINT `realisasi_pengajars_widyaiswara_id_foreign` FOREIGN KEY (`widyaiswara_id`) REFERENCES `widyaiswaras` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=325 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------
-- Records for `realisasi_pengajars`
-- -----------------------------

-- -----------------------------
-- Table structure for `ruangans`
-- -----------------------------
DROP TABLE IF EXISTS `ruangans`;
CREATE TABLE `ruangans` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nama_ruangan` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `kapasitas` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lokasi` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_aktif` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------
-- Records for `ruangans`
-- -----------------------------

-- -----------------------------
-- Table structure for `sessions`
-- -----------------------------
DROP TABLE IF EXISTS `sessions`;
CREATE TABLE `sessions` (
  `id` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `user_id` bigint unsigned DEFAULT NULL,
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` text COLLATE utf8mb4_unicode_ci,
  `payload` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_activity` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `sessions_user_id_index` (`user_id`),
  KEY `sessions_last_activity_index` (`last_activity`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------
-- Records for `sessions`
-- -----------------------------

-- -----------------------------
-- Table structure for `users`
-- -----------------------------
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nik` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `username` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `phone` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `role` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'penyelenggara',
  `avatar` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('Aktif','Nonaktif') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Aktif',
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `remember_token` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  UNIQUE KEY `users_username_unique` (`username`),
  UNIQUE KEY `users_nik_unique` (`nik`)
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------
-- Records for `users`
-- -----------------------------

-- -----------------------------
-- Table structure for `widyaiswaras`
-- -----------------------------
DROP TABLE IF EXISTS `widyaiswaras`;
CREATE TABLE `widyaiswaras` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `nik` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nip` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `nama_lengkap` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `gelar_depan` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gelar_belakang` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `jabatan` enum('Widyaiswara Ahli Pertama','Widyaiswara Ahli Muda','Widyaiswara Ahli Madya','Widyaiswara Ahli Utama') COLLATE utf8mb4_unicode_ci NOT NULL,
  `instansi` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PPSDM',
  `nomor_telepon` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `status` enum('Aktif','Nonaktif') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Aktif',
  `keterangan` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `widyaiswaras_nik_unique` (`nik`),
  UNIQUE KEY `widyaiswaras_nip_unique` (`nip`)
) ENGINE=InnoDB AUTO_INCREMENT=213 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- -----------------------------
-- Records for `widyaiswaras`
-- -----------------------------

